/// A C observer: degrees and metres, validated into a `Place` on the
/// way in.
#[napi(object)]
#[derive(Clone, Debug)]
pub struct Observer {
    /// Degrees, east positive.
    pub longitude_deg: f64,
    /// Degrees, north positive.
    pub latitude_deg: f64,
    /// Metres above sea level.
    pub altitude_m: f64,
}

/// What a `Observer` lends the C struct built from it: the buffers its
/// pointers point into, alive for as long as this value is.
pub struct HeldObserver {
    longitude_deg: f64,
    latitude_deg: f64,
    altitude_m: f64,
}

impl HeldObserver {
    /// The C struct, borrowing this value's buffers.
    pub fn as_c(&self) -> port::vtable::ObserverC {
        port::vtable::ObserverC {
            longitude_deg: self.longitude_deg,
            latitude_deg: self.latitude_deg,
            altitude_m: self.altitude_m,
        }
    }
}

impl Observer {
    /// The buffers and values the C struct is built from.
    pub fn read(&self) -> Result<HeldObserver> {
        Ok(HeldObserver {
            longitude_deg: self.longitude_deg as f64,
            latitude_deg: self.latitude_deg as f64,
            altitude_m: self.altitude_m as f64,
        })
    }

    /// The object a call filled.
    ///
    /// # Safety
    ///
    /// Every pointer in `raw` must be valid as the struct documents, for
    /// the length of this call.
    pub unsafe fn write(raw: &port::vtable::ObserverC) -> Self {
        Observer {
            longitude_deg: raw.longitude_deg as _,
            latitude_deg: raw.latitude_deg as _,
            altitude_m: raw.altitude_m as _,
        }
    }
}

